# frozen_string_literal: true

require "bundler/inline"

gemfile do
  source "https://rubygems.org"
  gem "rspec", "~> 3.13"
end

require "rspec/autorun"

require "fileutils"
require "open3"
require "tmpdir"

SCRIPT = File.expand_path("set-up-steam", __dir__)

STEAM_WRAPPER = <<~BASH
  #!/bin/bash
  # autogenerated file - do not edit

  open steam://run/2868840

BASH

PATCHED_WRAPPER = <<~BASH
  #!/bin/bash
  # autogenerated file - do not edit

  if pgrep -xq steam_osx; then
    open steam://run/2868840
  else
    open -g -a Steam --args -silent -applaunch 2868840
  fi
BASH

describe "set-up-steam" do
  subject(:run_script) { Open3.capture3({ "HOME" => @home_directory }, SCRIPT) }

  around do |example|
    Dir.mktmpdir do |directory|
      @home_directory = directory
      example.run
    end
  end

  def write_wrapper(name, contents)
    path = File.join(@home_directory, "Applications", "#{name}.app", "Contents", "MacOS", "run.sh")
    FileUtils.mkdir_p(File.dirname(path))
    File.write(path, contents)
    path
  end

  context "when a Steam wrapper is unpatched" do
    let!(:wrapper) { write_wrapper("Slay the Spire 2", STEAM_WRAPPER) }

    it "patches the wrapper" do
      run_script
      expect(File.read(wrapper)).to eq(PATCHED_WRAPPER)
    end

    it "succeeds" do
      expect(run_script.last).to be_success
    end
  end

  context "when a Steam wrapper is already patched" do
    let!(:wrapper) { write_wrapper("Slay the Spire 2", PATCHED_WRAPPER) }

    it "leaves it unchanged" do
      run_script
      expect(File.read(wrapper)).to eq(PATCHED_WRAPPER)
    end
  end

  context "when another app has a run.sh" do
    let(:contents) { "#!/bin/bash\nopen -a Safari\n" }
    let!(:wrapper) { write_wrapper("Other", contents) }

    it "leaves it alone" do
      run_script
      expect(File.read(wrapper)).to eq(contents)
    end
  end

  context "when there are no wrappers" do
    it "succeeds" do
      expect(run_script.last).to be_success
    end
  end
end
